lass="form-control" name="caption" rows="3"></textarea></div></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Để sau</button><button class="btn btn-brand">Gửi chờ duyệt</button></div></form></div></div></div><?php endforeach; ?></div>
